<?php if(!defined('ABSPATH'))exit;$d=woogit_portal_data();get_header();if(!$d['authenticated']){woogit_render_status('error','نشست شما منقضی شده است.');get_footer();return;}$b=$d['billing'];$pm=$d['payment_method'];$billingStatus=woogit_portal_status(woogit_portal_value($b,['billing_status','payment_status'],'وضعیت نامشخص'));$subscriptionStatus=woogit_portal_status(woogit_portal_value($b,['status','subscription_status'],'نامشخص'));?><section class="wg-section wg-portal"><div class="wg-container"><div class="wg-section__head"><div><span class="wg-eyebrow">صورتحساب</span><h1>صورتحساب</h1><p>وضعیت اشتراک، صورتحساب و روش پرداخت شما در این بخش نمایش داده می‌شود.</p></div></div><div class="wg-grid wg-grid--2"><article class="wg-card"><span>اشتراک فعلی</span><h2><?php echo woogit_safe_text(woogit_portal_value($b,['plan_name','plan.name','plan'],'—')); ?></h2><p>وضعیت: <span class="wg-status wg-status--<?php echo esc_attr($subscriptionStatus[1]); ?>"><?php echo woogit_safe_text($subscriptionStatus[0]); ?></span></p><p>تمدید بعدی: <?php echo woogit_safe_text(woogit_portal_value($b,['next_billing_at','renews_at'],'—')); ?></p></article><article class="wg-card"><span>روش پرداخت</span><?php if($pm): ?><h2><?php echo woogit_safe_text($pm['payment_method_title']??$pm['payment_method']??'—'); ?></h2><p>روش پرداخت ثبت‌شده شما در اینجا نمایش داده می‌شود.</p><?php else: ?><h2>اطلاعاتی ثبت نشده</h2><p>پس از ثبت پرداخت، روش پرداخت شما در این بخش نمایش داده می‌شود.</p><?php endif; ?></article></div><div class="wg-card"><h2>وضعیت مالی</h2><p><span class="wg-status wg-status--<?php echo esc_attr($billingStatus[1]); ?>"><?php echo woogit_safe_text($billingStatus[0]); ?></span></p><a class="wg-btn" href="<?php echo esc_url(woogit_page_url('payments')); ?>">مشاهده پرداخت‌ها</a></div></div></section><?php get_footer(); ?>